<?php
$a=admin_appointment($reference);$s=payment_summary($a);$start=local_time($a['starts_at']);$end=local_time($a['ends_at']);
?>
<article class="booking-sheet"><p class="eyebrow">Booking reference · <?= e(appointment_status_label($a['status'])) ?></p>
<?php $copyReference=$a['booking_reference']; require __DIR__.'/../booking-reference.php'; ?><h2><?= e($a['service_name_snapshot']?:$a['catalog_name']) ?></h2>
<dl class="details-grid"><?php foreach(['Customer'=>$a['customer_name'],'Email'=>$a['customer_email'],'Room / guests'=>$a['room_code'].' / '.$a['guest_count'],'Assigned therapists'=>staff_display_name($a['therapist_names']?:'Not assigned'),'Appointment'=>$start->format('F j, Y · g:i A').'–'.$end->format('g:i A'),'Cleaning until'=>local_time($a['cleaning_ends_at'])->format('g:i A'),'Total'=>peso_amount($s['total']),'Amount recorded'=>peso_amount($s['paid']),'Remaining balance'=>peso_amount($s['balance']),'Payment status'=>payment_status_label($a)] as $label=>$value): ?><div><dt><?= e($label) ?></dt><dd><?= e($value) ?></dd></div><?php endforeach; ?></dl>
<?php if($s['is_demo']): ?><p class="notice"><strong>Test checkout — No actual funds will be transferred.</strong> <a class="text-link" href="<?= e(url('/admin/payments.php?search='.rawurlencode($a['booking_reference']))) ?>">View payment history ↗</a></p><?php endif; ?><p class="small-note">Medical answers are deliberately not exposed in this administration view.</p></article>
<div class="staff-form-grid">
<?php $transitions=['pending'=>['confirmed'],'confirmed'=>['ongoing','completed','no_show'],'ongoing'=>['completed']];if(isset($transitions[$a['status']])): ?>
<form method="post" class="booking-sheet"><?php admin_action_fields($a,'status'); ?><h2>Appointment status.</h2><div class="field"><label for="new-status">New status</label><select id="new-status" name="status"><?php foreach($transitions[$a['status']] as $status): ?><option value="<?= e($status) ?>"><?= e(str_replace('_',' ',$status)) ?></option><?php endforeach; ?></select></div><button class="button" type="submit">Save valid status ↗</button><p class="small-note">The server enforces treatment times. A checkout hold cannot be manually confirmed here.</p></form><?php endif; ?>
<?php if(in_array($a['status'],['pending','confirmed','ongoing','awaiting_payment'],true)): ?><form method="post" class="booking-sheet"><?php admin_action_fields($a,'cancel'); ?><h2>Cancel appointment.</h2><div class="field"><label for="admin-reason">Reason</label><textarea id="admin-reason" name="reason" required minlength="3" maxlength="1000" rows="3"></textarea></div><p class="small-note">Administrator cancellation can override the customer notice deadline. Late cancellations forfeit any recorded downpayment. Other refund decisions require review.</p><button class="button clay-button" type="submit">Record cancellation ↗</button></form><?php endif; ?>
<?php if(in_array($a['status'],['confirmed','pending'],true)&&$start>new DateTimeImmutable('now',spa_timezone())):
    $window=appointment_window(reschedule_service($a),$start->format('Y-m-d'),$start->format('H:i'));$candidates=available_therapists($window,(int)$a['id'],(int)$a['service_id']);
?>
<form method="post" class="booking-sheet"><?php admin_action_fields($a,'assign'); ?><h2>Assign therapists.</h2><p>Select exactly <?= e(required_therapists((int)$a['service_id'])) ?> available therapist(s).</p><div class="field"><label for="assign-therapists">Available for the full treatment</label><select id="assign-therapists" name="therapist_ids[]" multiple required size="4"><?php foreach($candidates as $t): ?><option value="<?= e($t['id']) ?>"><?= e($t['full_name']) ?></option><?php endforeach; ?></select></div><button class="button" type="submit">Save assignment ↗</button></form>
<form method="post" class="booking-sheet"><?php admin_action_fields($a,'reschedule'); ?><h2>Move the visit.</h2><div class="field"><label for="admin-date">New date</label><input id="admin-date" type="date" name="date" min="<?= (new DateTimeImmutable('today',spa_timezone()))->format('Y-m-d') ?>" required></div><div class="field"><label for="admin-time">New start · Philippine time</label><input id="admin-time" type="time" name="time" min="13:00" max="20:00" step="1800" required></div><p class="small-note">Original resources remain reserved until the replacement passes room, cleaning, staffing and closing checks. Payments and price remain attached.</p><button class="button" type="submit">Save safe reschedule ↗</button></form><?php endif; ?>
</div>
<?php $q=db()->prepare('SELECT * FROM refund_requests WHERE appointment_id=? ORDER BY id');$q->execute([$a['id']]);$reviews=$q->fetchAll();if($reviews): ?>
<section class="booking-sheet"><h2>Refund policy review.</h2><?php foreach($reviews as $review): ?><p><?= $review['is_demo']?'Test payment review':'Real payment review' ?> · <?= e($review['status']) ?> · <?= e($review['admin_note']??'No decision note yet.') ?></p><?php endforeach; ?>
<form method="post"><?php admin_action_fields($a,'refund_review'); ?><div class="field"><label for="review-status">Review state</label><select id="review-status" name="review_status"><option value="pending_admin_review">Pending administrator review</option><option value="resolved">Review resolved — no automatic refund</option></select></div><div class="field"><label for="review-note">Review note / policy decision</label><textarea id="review-note" name="note" required minlength="3" maxlength="1000" rows="3"></textarea></div><button class="button" type="submit">Save review ↗</button></form></section><?php endif; ?>
<?php $q=db()->prepare('SELECT action,created_at FROM appointment_changes WHERE appointment_id=? ORDER BY id DESC');$q->execute([$a['id']]);$changes=$q->fetchAll(); ?>
<section class="change-history"><h2>Appointment change history.</h2><ul><?php foreach($changes as $change): ?><li><?= e(local_time($change['created_at'])->format('M j · g:i A').' · '.appointment_change_label($change['action'])) ?></li><?php endforeach; ?></ul>
<?php if(array_intersect(['rescheduled','admin_reschedule'],array_column($changes,'action'))): ?><form method="post"><?php admin_action_fields($a,'review_reschedule'); ?><button class="text-link" type="submit">Record rescheduling review ↗</button></form><?php endif; ?></section>
